void emitstr(int* a, int n)  {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void)  {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    // 先更新这一侧最高值，再加最高值与当前柱高的差，刷新最高值时贡献为 0。
    int ans = 0, i = 0, l = 0, lm = 0, n = 0, r = 0, rm = 0;
