        a[i] = read();
    }
    l = 0;
    r = (n - 1);
    lm = 0;
    rm = 0;
    ans = 0;
    while (l <= r)  {
        // 先结算已见最高墙较低的一侧，另一侧已经提供足够高的边界。
        if (lm <= rm)  {
